            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Anyone can do that - the stunt lies in not doing it.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "I thought that was going to be a good song, too, and then they went and rhymed \"time\" and \"Rhine,\" and spoiled everything.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "They exude an atmosphere of The New Republic - a sort of Crolier-than-thou air.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "There is one thing about Fiddlers Three, though, that held my attention all through the evening: Try as I might I could only discern two fiddlers.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "If the English version is in what, in our youth, we used to speak of affectionately as dear old iambic pentameter, the actors mercifully abstain from reciting it that way; they speak their lines as good, hardy prose.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "The musical comedies of the month are She's a Good Fellow and The Lady in Red, both of which owe their book and lyrics to Anne Caldwell - evidently a native of New York, judged by the casualness with which she rhymes \"teacher\" and \"reach a.\"", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "And you remember, Rabbi Wise has declared, in a heated moment, that our plays seem to be written for the hosiery buyers. If Dr. Wise had only witnessed our new summer reviews, he doubtless would have amended his statement to \"read by the hosiery buyers.\"", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "This use of soldiers to make a play popular seems too much like taking an unfair advantage of the uniform - hitting below the Sam Browne belt, as it were.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Writing a book for the Follies seems to be about as profitable an occupation as furnishing flannel petticoats for the showgirls.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "The management's method of procedure is evidently to hire some well-known man to write the book, and then, as soon as it is written, to give it away to some deserving family, and go out and engage an assortment of specialty acts.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Van and Schenck put their songs over so skillfully that it isn't until their act is all done that you realize what extremely indifferent songs they are. Now, when John Steel is singing, on the other hand, you are never fooled for a moment.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Mr. Hodge plays with his accustomed ease, even carrying the thing so far as to repeat many of his lines with his eyes shut; and in a pretty spirit of reciprocity, many members of the audience sit through the play with their eyes shut.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Of course, there are many things to be said for the afternoon performance, chief among them being that it cuts in so generously on one's work.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Naturally, you know how you would feel on setting out to see a performance of Aucassin and Nicolette done by a company of little ones; you would strive to hurl yourself beneath the wheels of a friendly truck, on your way to the theatre.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Bringing in a wounded soldier is getting to be rather like waving an American flag at the end of an act. One cannot harbor feelings of unmixed admiration for the playwright who will hide behind either of them.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "If you arrive late, you won't know what anything is about, and if you are there all the way from the beginning, you won't care.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "There is one thing that appreciably eases the strain for the plays that arrive at this time of year, and that is that practically nothing is expected of them.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "It is advertised as \"a seagoin' comedy,\" and anytime they go leaving off the final g that way, you know what to expect.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Two things made The Dice of the Gods, another play about drugs, seem much better than it had any real right to seem. One was that Morphia had come first, and once you had seen Morphia, nothing seemed so very terrible to you.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Get me a new husband.", Author = "Dorothy Parker" },
